--    Both sides are timestamptz, so the lease arithmetic is timezone-correct without a cast.

CREATE OR REPLACE FUNCTION __mj."spClaimCompanyIntegrationRun"(
    IN p_RunID        UUID,
    IN p_OwnerToken   UUID,
    IN p_LeaseMinutes INTEGER
)
RETURNS TABLE("FenceToken" INTEGER, "LeaseExpiresAt" TIMESTAMPTZ) AS
$mjfn$
BEGIN
    -- Single atomic claim: succeeds only if unowned or the lease expired.
    RETURN QUERY
    WITH "claimed" AS (
        UPDATE __mj."CompanyIntegrationRun" AS "cir"
           SET "OwnerToken"     = p_OwnerToken,
               "LeaseExpiresAt" = NOW() + make_interval(mins => p_LeaseMinutes),
               "HeartbeatAt"    = NOW(),
               "FenceToken"     = "cir"."FenceToken" + 1
         WHERE "cir"."ID" = p_RunID
           AND ("cir"."OwnerToken" IS NULL
                OR "cir"."LeaseExpiresAt" IS NULL
                OR "cir"."LeaseExpiresAt" < NOW())
        RETURNING "cir"."FenceToken", "cir"."LeaseExpiresAt"
    )
    -- Zero rows = claim lost; the caller must not proceed.
    SELECT "claimed"."FenceToken", "claimed"."LeaseExpiresAt" FROM "claimed";
END;
$mjfn$ LANGUAGE plpgsql;

