COMMENT ON FUNCTION __mj."spRenewCompanyIntegrationRunLease" IS 'Atomically renews (extends) the owning process''s lease on a CompanyIntegrationRun IF AND ONLY IF both OwnerToken and FenceToken still match — a stale or reclaimed holder cannot renew a fresh holder''s lease (same lost-mutex protection as spExtendScheduledJobLease). Optionally updates ProgressJSON in the same statement. Returns the (unchanged) FenceToken, new LeaseExpiresAt, and CancelRequestedAt so the timer heartbeat doubles as the cross-process cancel check; ZERO rows returned = the run was reclaimed and the caller must abort without writing. Called from a timer at roughly one third of the lease interval, with the run''s configured MaxRuntimeMinutes-derived lease — so a single long batch cannot make a healthy run look dead.';

CREATE OR REPLACE FUNCTION __mj."spReleaseCompanyIntegrationRun"(
    IN p_RunID       UUID,
    IN p_OwnerToken  UUID,
    IN p_FinalStatus VARCHAR(20),
    IN p_FenceToken  INTEGER DEFAULT NULL
)
RETURNS TABLE("ID" UUID) AS
$mjfn$
BEGIN
    -- The fence is checked here for the same reason spRenewCompanyIntegrationRunLease checks it:
    -- OwnerToken alone proves "some context using this token owns the row", not "THIS context
    -- still owns it". Optional, so a caller that has not yet been updated behaves as before.
    RETURN QUERY
    WITH "released" AS (
        UPDATE __mj."CompanyIntegrationRun" AS "cir"
           SET "Status"         = p_FinalStatus,
               "OwnerToken"     = NULL,
               "LeaseExpiresAt" = NULL,
               "EndedAt"        = COALESCE("cir"."EndedAt", NOW())
         WHERE "cir"."ID" = p_RunID
           AND "cir"."OwnerToken" = p_OwnerToken
           AND (p_FenceToken IS NULL OR "cir"."FenceToken" = p_FenceToken)
        RETURNING "cir"."ID"
    )
    -- Zero rows = we no longer owned the run (reclaimed); the release is a no-op.
    SELECT "released"."ID" FROM "released";
END;
$mjfn$ LANGUAGE plpgsql;

