DO $$ BEGIN GRANT EXECUTE ON FUNCTION __mj."spReleaseCompanyIntegrationRun" TO "cdp_Integration"; EXCEPTION WHEN others THEN NULL; END $$;

COMMENT ON FUNCTION __mj."spReleaseCompanyIntegrationRun" IS 'Releases ownership of a CompanyIntegrationRun, setting the terminal Status and clearing OwnerToken/LeaseExpiresAt (EndedAt is stamped if not already set) — but ONLY if the caller''s OwnerToken still matches. A stale holder''s release is a harmless no-op (zero rows returned) because a reclaim already replaced the token. Called by the engine on normal completion/failure and by the worker after execution.';

/* ─── 5. RSUPendingWork — durable replacement for the .rsu_pending dir ─ */
/* The former mechanism was a directory of ${Date.now()}.json files with */
/* delete-BEFORE-process semantics: a crash between read and process silently */
/* lost the work, and corrupt files were silently skipped. Rows here are */
/* completed only after the work succeeds; failures record the error and */
/* leave the row visible. */
CREATE TABLE __mj."RSUPendingWork" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CompanyIntegrationID" UUID NOT NULL,
  "PayloadJSON" TEXT NOT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Pending',
  "ErrorMessage" TEXT NULL,
  "ProcessedAt" TIMESTAMPTZ NULL,
  CONSTRAINT "PK_RSUPendingWork" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_RSUPendingWork_CompanyIntegration" FOREIGN KEY ("CompanyIntegrationID") REFERENCES __mj."CompanyIntegration" (
    "ID"
  ),
  CONSTRAINT "CK_RSUPendingWork_Status" CHECK ("Status" = 'Pending' OR "Status" = 'Completed' OR "Status" = 'Failed')
);

COMMENT ON TABLE __mj."RSUPendingWork" IS 'Durable queue of Runtime Schema Update (RSU) pending setup work that must survive a server restart — replaces the former .rsu_pending directory of delete-on-read JSON files. A row is inserted when post-restart work is registered, marked Completed only AFTER the work succeeds, and marked Failed with ErrorMessage on error (never deleted on read), so stranded work older than N minutes is queryable instead of silently lost.';

COMMENT ON COLUMN __mj."RSUPendingWork"."PayloadJSON" IS 'The RSU pending-work payload (the RSUPendingWork JSON shape: SourceObjectNames, SchemaName, sync/schedule options). Stored as JSON so the payload can evolve without schema churn; only the RSU pipeline interprets it.';

COMMENT ON COLUMN __mj."RSUPendingWork"."Status" IS 'Lifecycle state of this pending work item. Pending = registered, not yet processed (rows Pending for longer than expected indicate stranded work). Completed = the post-restart consumer finished successfully. Failed = processing errored; see ErrorMessage.';

COMMENT ON COLUMN __mj."RSUPendingWork"."ErrorMessage" IS 'Error detail recorded when processing this work item failed. The row is left in place (Status=Failed) rather than deleted, so failures are visible and re-runnable.';

COMMENT ON COLUMN __mj."RSUPendingWork"."ProcessedAt" IS 'When the post-restart consumer finished processing this row (success or failure). NULL while Pending.';

